    require record.scientific_status in {supported, provisional}
    occupancy = occupancy or 1                                     # divide only when the user stated it
    result_kg = round(quantity * record.value / occupancy, 3)

The agent supplies only the four parameters. It cannot supply a factor value. The executor looks the value up. The attester re-reads the registry by `factor_id` and `dataset_version`, recomputes `result_kg`, checks that the registry file hash matches `registry_sha256`, and compares the result with both the receipt and the number displayed to the user.', '831ca585a7652606de9432568f8fcca482d70b7b4b73421e7b4c5a38a276b2a0', 89, 'ANY', '[-0.0048694,-0.0279173,0.0187487,-0.0387308,0.0097511,0.0326813,0.0089126,0.0583832,0.0405833,0.0064880,-0.0290608,-0.0203274,0.0367692,-0.0558542,0.0096937,0.0529450,0.0441936,-0.0651223,-0.0013989,0.0138047,0.0334317,-0.0445115,-0.0448065,-0.0110907,-0.0414338,-0.0444054,-0.0200570,0.0341272,-0.0072579,0.0133449,-0.0248115,-0.0210999,0.0088920,-0.0408194,-0.0037863,0.0188810,0.0841712,-0.0064729,0.0409504,-0.0247190,-0.0290983,-0.0227623,0.0040968,0.0674319,-0.0005601,0.0227950,-0.0506548,-0.0378553,0.0349097,-0.0173272,0.0117391,-0.0100516,0.0018752,0.0097105,0.0386027,0.0798343,0.0159694,0.0556919,0.0463404,0.0632208,-0.0334891,0.0004745,-0.0364694,0.0341635,-0.0375731,0.0771592,0.0519040,0.0515303,0.0109242,-0.0633278,-0.0694628,0.0074372,0.0245066,-0.0526539,-0.0169392,-0.0309830,0.0363632,0.0069727,-0.0373090,0.0046415,-0.0552796,0.0261674,-0.0997806,-0.0005732,0.0678148,0.0332892,-0.0516352,-0.0630575,-0.0590565,0.0155197,-0.0348890,-0.0376405,0.0089737,-0.0657269,-0.0080605,0.0477151,0.0110762,0.0532351,-0.0427170,-0.0661887,-0.0482523,0.0257916,-0.0346165,-0.0167013,0.0294353,-0.0101827,-0.0708902,-0.0794637,-0.0142045,0.0343603,-0.0421170,-0.0302324,-0.0057562,0.0539602,0.0092849,0.0169693,-0.0026035,-0.0024188,-0.1163808,-0.0097850,-0.0398152,0.0552226,0.0721463,0.0293630,-0.0531722,-0.0788298,0.0171244,0.0145019,-0.0195697,-0.0201317,-0.0108011,-0.0483259,0.0284031,0.0601073,-0.0351869,0.0331835,-0.0134261,-0.0321284,0.0335267,0.0162862,-0.0022913,-0.0095738,-0.0231279,-0.0051699,-0.0032903,-0.0574936,0.0385098,0.0435412,0.03